var stoneGameIX = function(stones) {
    const buckets = Array(3).fill(0);

    for (const stone of stones) {
        buckets[stone % 3]++;
    }

    const memo = new Map();

    const bob = (of0, of1, of2, sum) => {
        if (of0 === 0 && of1 === 0 && of2 === 0) return true;

        const key = of0 + ':' + of1 + ':' + of2 + ':' + sum;
        if (memo.has(key)) return !memo.get(key);

        let res = false;

