        res ||= of1 > 0 && sum % 3 !== 2 && !alice(of0, of1 - 1, of2, sum + 1);
        res ||= of2 > 0 && sum % 3 !== 1 && !alice(of0, of1, of2 - 1, sum + 2);

        memo.set(key, !res);
        return res;
    };

    const alice = (of0, of1, of2, sum) => {
        if (of0 === 0 && of1 === 0 && of2 === 0) return false;

        const key = of0 + ':' + of1 + ':' + of2 + ':' + sum;
        if (memo.has(key)) return memo.get(key);

        let res = false;

        res ||= of0 > 0 && sum % 3 !== 0 && !bob(of0 - 1, of1, of2, sum);
