/**
 * @param {number[]} stones
 * @return {boolean}
 */
var stoneGameIX = function(stones) {
    const buckets = Array(3).fill(0);

    for (const stone of stones) {
        buckets[stone % 3]++;
    }

    if (buckets[0] % 2 === 0) {
        return buckets[1] >= 1 && buckets[2] >= 1;
    }
    return buckets[1] - buckets[2] > 2 || buckets[2] - buckets[1] > 2;
};
